commands.sqlStatement:
IF CAST([TF:TchpQcOrder.QcOrderId] AS INT) IS NULL
BEGIN
    RAISERROR(N'Save the QC Order first.', 16, 1);
    RETURN;
END

DECLARE @Oid INT = CAST([TF:TchpQcOrder.QcOrderId] AS INT);
DECLARE @Lot INT = ISNULL((SELECT LotQuantity FROM dbo.TchpQcOrder WHERE QcOrderId = @Oid), 0);
DECLARE @Sample INT;
DECLARE @AcC INT = 0;
DECLARE @AcM INT;
DECLARE @AcN INT;

SET @Sample = CASE
    WHEN @Lot <= 50 THEN 8
    WHEN @Lot <= 90 THEN 13
    WHEN @Lot <= 150 THEN 20
    WHEN @Lot <= 280 THEN 32
    WHEN @Lot <= 500 THEN 50
    WHEN @Lot <= 1200 THEN 80
    WHEN @Lot <= 3200 THEN 125
    ELSE 200
END;
SET @AcM = CASE
    WHEN @Lot <= 90 THEN 0
    WHEN @Lot <= 280 THEN 1
    WHEN @Lot <= 1200 THEN 3
    WHEN @Lot <= 3200 THEN 5
    ELSE 7
END;
SET @AcN = CASE
    WHEN @Lot <= 50 THEN 0
    WHEN @Lot <= 150 THEN 1
    WHEN @Lot <= 280 THEN 2
    WHEN @Lot <= 1200 THEN 5
    WHEN @Lot <= 3200 THEN 7
    ELSE 10
END;

IF NOT EXISTS (SELECT 1 FROM dbo.TchpQcOrderAql WHERE QcOrderId = @Oid)
    INSERT INTO dbo.TchpQcOrderAql (QcOrderId, AcCritical, AppCreatedDate, AppCreatedById)
    VALUES (@Oid, 0, GETDATE(), [CurrentUserId]);

UPDATE dbo.TchpQcOrder
SET SampleSize = @Sample, AppModifiedDate = GETDATE(), AppModifiedById = [CurrentUserId]
WHERE QcOrderId = @Oid;

DECLARE @FailC INT, @FailM INT, @FailN INT, @Sampled INT, @Completed INT, @CertFail BIT;

SELECT
    @Sampled = COUNT(*),
    @Completed = SUM(CASE WHEN i.InspectionStatus IN (N'COMPLETE', N'STOPPED_CRITICAL') THEN 1 ELSE 0 END),
    @FailC = SUM(CASE WHEN i.CriticalFail = 1 THEN 1 ELSE 0 END),
    @FailM = SUM(CASE WHEN i.MajorFail = 1 THEN 1 ELSE 0 END),
    @FailN = SUM(CASE WHEN i.MinorFail = 1 THEN 1 ELSE 0 END)
FROM dbo.TchpQcGarment AS g
LEFT JOIN dbo.TchpQcGarmentInspection AS i ON i.QcGarmentId = g.QcGarmentId
WHERE g.QcOrderId = @Oid;

SET @Sampled = ISNULL(@Sampled, 0);
SET @Completed = ISNULL(@Completed, 0);
SET @FailC = ISNULL(@FailC, 0);
SET @FailM = ISNULL(@FailM, 0);
SET @FailN = ISNULL(@FailN, 0);
SET @CertFail = CASE WHEN EXISTS (
    SELECT 1 FROM dbo.TchpQcOrderCert
    WHERE QcOrderId = @Oid AND IsRequired = 1 AND ISNULL(Result, N'PENDING') NOT IN (N'PASS', N'NA')
) THEN 1 ELSE 0 END;

DECLARE @Status NVARCHAR(20);
DECLARE @Aql NVARCHAR(20);
IF @CertFail = 1 OR @FailC > @AcC OR @FailM > @AcM OR @FailN > @AcN
BEGIN SET @Status = N'FAILED'; SET @Aql = N'FAILED'; END
ELSE IF @Completed >= @Sample AND @Sample > 0
BEGIN SET @Status = N'PASSED'; SET @Aql = N'PASSED'; END
ELSE IF @Sampled > 0
BEGIN SET @Status = N'IN_PROGRESS'; SET @Aql = N'PENDING'; END
ELSE
BEGIN SET @Status = N'OPEN'; SET @Aql = N'PENDING'; END

UPDATE dbo.TchpQcOrderAql
SET AcCritical = @AcC, AcMajor = @AcM, AcMinor = @AcN,
    FailCriticalCount = @FailC, FailMajorCount = @FailM, FailMinorCount = @FailN,
    SampledCount = @Sampled, CompletedCount = @Completed,
    CertFail = @CertFail, AqlPassStatus = @Aql,
    AppModifiedDate = GETDATE(), AppModifiedById = [CurrentUserId]
WHERE QcOrderId = @Oid;

UPDATE dbo.TchpQcOrder
SET OrderStatus = @Status, AppModifiedDate = GETDATE(), AppModifiedById = [CurrentUserId]
WHERE QcOrderId = @Oid;

IF CAST([TF:TchpQcGarment.QcGarmentId] AS INT) IS NULL
BEGIN
    RAISERROR(N'Save the garment first.', 16, 1);
    RETURN;
END

DECLARE @Gid INT = CAST([TF:TchpQcGarment.QcGarmentId] AS INT);
DECLARE @Oid INT = CAST([TF:TchpQcGarment.QcOrderId] AS INT);

IF NOT EXISTS (SELECT 1 FROM dbo.TchpQcGarmentInspection WHERE QcGarmentId = @Gid)
    INSERT INTO dbo.TchpQcGarmentInspection (QcGarmentId, InspectionStatus, AppCreatedDate, AppCreatedById)
    VALUES (@Gid, N'OPEN', GETDATE(), [CurrentUserId]);

UPDATE d
SET DefectClass = ISNULL(c.DefectClass, ISNULL(d.DefectClass, N'MINOR')),
    InspectionTrack = ISNULL(c.InspectionTrack, d.InspectionTrack),
    AppModifiedDate = GETDATE(),
    AppModifiedById = [CurrentUserId]
FROM dbo.TchpQcDefectRecord AS d
LEFT JOIN dbo.TchpQcDefectCode AS c ON c.DefectCode = d.DefectCode
WHERE d.QcGarmentId = @Gid;

UPDATE r
SET Pass = CASE
        WHEN COALESCE(r.AfterIronValue, r.AfterWashValue, r.BeforeWashValue, r.ProductionValue) IS NULL THEN NULL
        WHEN ABS(COALESCE(r.AfterIronValue, r.AfterWashValue, r.BeforeWashValue, r.ProductionValue) - r.SpecValue) <= r.Tolerance THEN 1
        ELSE 0
    END,
    DefectClass = CASE
        WHEN COALESCE(r.AfterIronValue, r.AfterWashValue, r.BeforeWashValue, r.ProductionValue) IS NULL THEN r.DefectClass
        WHEN ABS(COALESCE(r.AfterIronValue, r.AfterWashValue, r.BeforeWashValue, r.ProductionValue) - r.SpecValue) <= r.Tolerance THEN NULL
        ELSE N'MAJOR'
    END,
    AppModifiedDate = GETDATE(),
    AppModifiedById = [CurrentUserId]
FROM dbo.TchpQcResult AS r
WHERE r.QcGarmentId = @Gid;

DECLARE @Crit BIT = CASE WHEN EXISTS (SELECT 1 FROM dbo.TchpQcDefectRecord WHERE QcGarmentId = @Gid AND DefectClass = N'CRITICAL') THEN 1 ELSE 0 END;
DECLARE @Maj BIT = CASE WHEN EXISTS (SELECT 1 FROM dbo.TchpQcDefectRecord WHERE QcGarmentId = @Gid AND DefectClass = N'MAJOR')
    OR EXISTS (SELECT 1 FROM dbo.TchpQcResult WHERE QcGarmentId = @Gid AND Pass = 0) THEN 1 ELSE 0 END;
DECLARE @Min BIT = CASE WHEN EXISTS (SELECT 1 FROM dbo.TchpQcDefectRecord WHERE QcGarmentId = @Gid AND DefectClass = N'MINOR') THEN 1 ELSE 0 END;
DECLARE @PomTotal INT, @PomMeasured INT;
SELECT @PomTotal = COUNT(*), @PomMeasured = SUM(CASE WHEN Pass IS NOT NULL THEN 1 ELSE 0 END)
FROM dbo.TchpQcResult WHERE QcGarmentId = @Gid;
SET @PomTotal = ISNULL(@PomTotal, 0);
SET @PomMeasured = ISNULL(@PomMeasured, 0);

DECLARE @Status NVARCHAR(20);
DECLARE @Pass BIT;
DECLARE @Stop NVARCHAR(200);
IF @Crit = 1
BEGIN
    SET @Status = N'STOPPED_CRITICAL';
    SET @Pass = 0;
    SET @Stop = N'Critical safety defect — remaining checks skipped';
END
ELSE IF @PomTotal > 0 AND @PomMeasured >= @PomTotal
BEGIN
    SET @Status = N'COMPLETE';
    SET @Pass = CASE WHEN @Maj = 1 OR @Min = 1 THEN 0 ELSE 1 END;
    SET @Stop = NULL;
END
ELSE
BEGIN
    SET @Status = N'OPEN';
    SET @Pass = CASE WHEN @Maj = 1 OR @Min = 1 THEN 0 ELSE NULL END;
    SET @Stop = NULL;
END

UPDATE dbo.TchpQcGarmentInspection
SET InspectionStatus = @Status, CriticalFail = @Crit, MajorFail = @Maj, MinorFail = @Min,
    StopReason = @Stop, InspectedAt = GETDATE(), InspectorId = [CurrentUserId],
    AppModifiedDate = GETDATE(), AppModifiedById = [CurrentUserId]
WHERE QcGarmentId = @Gid;

UPDATE dbo.TchpQcGarment
SET GarmentPassStatus = @Pass, AppModifiedDate = GETDATE(), AppModifiedById = [CurrentUserId]
WHERE QcGarmentId = @Gid;

IF @Oid IS NULL RETURN;

DECLARE @Lot INT = ISNULL((SELECT LotQuantity FROM dbo.TchpQcOrder WHERE QcOrderId = @Oid), 0);
DECLARE @Sample INT = CASE WHEN @Lot <= 50 THEN 8 WHEN @Lot <= 90 THEN 13 WHEN @Lot <= 150 THEN 20 WHEN @Lot <= 280 THEN 32 WHEN @Lot <= 500 THEN 50 WHEN @Lot <= 1200 THEN 80 WHEN @Lot <= 3200 THEN 125 ELSE 200 END;
DECLARE @AcC INT = 0;
DECLARE @AcM INT = CASE WHEN @Lot <= 90 THEN 0 WHEN @Lot <= 280 THEN 1 WHEN @Lot <= 1200 THEN 3 WHEN @Lot <= 3200 THEN 5 ELSE 7 END;
DECLARE @AcN INT = CASE WHEN @Lot <= 50 THEN 0 WHEN @Lot <= 150 THEN 1 WHEN @Lot <= 280 THEN 2 WHEN @Lot <= 1200 THEN 5 WHEN @Lot <= 3200 THEN 7 ELSE 10 END;
IF NOT EXISTS (SELECT 1 FROM dbo.TchpQcOrderAql WHERE QcOrderId = @Oid)
    INSERT INTO dbo.TchpQcOrderAql (QcOrderId, AcCritical, AppCreatedDate) VALUES (@Oid, 0, GETDATE());

DECLARE @FailC INT, @FailM INT, @FailN INT, @Sampled INT, @Completed INT, @CertFail BIT;
SELECT @Sampled = COUNT(*),
    @Completed = SUM(CASE WHEN i.InspectionStatus IN (N'COMPLETE', N'STOPPED_CRITICAL') THEN 1 ELSE 0 END),
    @FailC = SUM(CASE WHEN i.CriticalFail = 1 THEN 1 ELSE 0 END),
    @FailM = SUM(CASE WHEN i.MajorFail = 1 THEN 1 ELSE 0 END),
    @FailN = SUM(CASE WHEN i.MinorFail = 1 THEN 1 ELSE 0 END)
FROM dbo.TchpQcGarment AS g
LEFT JOIN dbo.TchpQcGarmentInspection AS i ON i.QcGarmentId = g.QcGarmentId
WHERE g.QcOrderId = @Oid;
SET @Sampled = ISNULL(@Sampled, 0); SET @Completed = ISNULL(@Completed, 0);
SET @FailC = ISNULL(@FailC, 0); SET @FailM = ISNULL(@FailM, 0); SET @FailN = ISNULL(@FailN, 0);
SET @CertFail = CASE WHEN EXISTS (SELECT 1 FROM dbo.TchpQcOrderCert WHERE QcOrderId = @Oid AND IsRequired = 1 AND ISNULL(Result, N'PENDING') NOT IN (N'PASS', N'NA')) THEN 1 ELSE 0 END;
DECLARE @OStatus NVARCHAR(20); DECLARE @Aql NVARCHAR(20);
IF @CertFail = 1 OR @FailC > @AcC OR @FailM > @AcM OR @FailN > @AcN BEGIN SET @OStatus = N'FAILED'; SET @Aql = N'FAILED'; END
ELSE IF @Completed >= @Sample AND @Sample > 0 BEGIN SET @OStatus = N'PASSED'; SET @Aql = N'PASSED'; END
ELSE IF @Sampled > 0 BEGIN SET @OStatus = N'IN_PROGRESS'; SET @Aql = N'PENDING'; END
ELSE BEGIN SET @OStatus = N'OPEN'; SET @Aql = N'PENDING'; END
UPDATE dbo.TchpQcOrderAql SET AcCritical = @AcC, AcMajor = @AcM, AcMinor = @AcN, FailCriticalCount = @FailC, FailMajorCount = @FailM, FailMinorCount = @FailN, SampledCount = @Sampled, CompletedCount = @Completed, CertFail = @CertFail, AqlPassStatus = @Aql, AppModifiedDate = GETDATE(), AppModifiedById = [CurrentUserId] WHERE QcOrderId = @Oid;
UPDATE dbo.TchpQcOrder SET SampleSize = @Sample, OrderStatus = @OStatus, AppModifiedDate = GETDATE(), AppModifiedById = [CurrentUserId] WHERE QcOrderId = @Oid;
